#pragma once
template<class Check>void arrangementTests(Window &w,const QString &output,Check check){
 auto reset=[&]{w.logicalView=false;w.uml=false;w.en=false;w.mode=1;w.model=Model::example();w.history.clear();w.selection.clear();w.selectionIds.clear();w.view->gridVisible=false;w.view->snapEnabled=false;w.view->dragAlt=false;w.applyTheme();w.buildMenus();w.refresh();};reset();
 auto near=[](double a,double b){return std::abs(a-b)<.001;};
 auto before=w.model.json();w.findChild<QAction*>("showGrid")->trigger();w.findChild<QAction*>("snapGrid")->trigger();check("Grid and snapping toggles do not move or dirty the document",w.model.json()==before&&w.history.isClean()&&w.view->gridVisible&&w.view->snapEnabled);
 w.selectOnly("ordine");w.pick("riga",2);w.dragBefore=w.model;w.dragIds=w.selectionIds;auto start=w.nodes["riga"]->pos()+w.gridOffset("riga");auto delta=w.snappedDrag({17,13});check("Grid snaps group reference top-left",View::nearestGrid(start+delta)==start+delta);
 w.moveDrag({17,13});check("Grid drag retains group spacing and carries Chen attributes once",w.model.get("ordine")->chen-w.dragBefore.get("ordine")->chen==delta&&w.model.get("numordine")->chen-w.dragBefore.get("numordine")->chen==delta&&w.model.get("riga")->chen-w.dragBefore.get("riga")->chen==delta);
 w.finishGroupDrag();check("Grid drag is one undo step",w.history.count()==1);w.history.undo();check("Grid drag undo restores entire project",w.model.json()==before);
 w.view->dragAlt=true;check("Alt bypasses snapping",w.snappedDrag({7,9})==QPointF(7,9));w.view->dragAlt=false;
 check("Grid handles negative coordinates",View::nearestGrid({-29,-31})==QPointF(-20,-40));w.view->resetTransform();w.view->scale(.1,.1);check("Grid thins out when zooming far out",w.view->visibleGridStep()>20);w.view->resetTransform();
 for(bool uml:{false,true}){
  w.uml=uml;w.refresh();w.selectOnly("ordine");w.pick("riga",2);auto old=w.model;w.arrangeSelection(6);bool snapped=true;for(auto id:{"ordine","riga"}){auto p=w.nodes[id]->pos()+w.gridOffset(id);snapped&=near(p.x()/20,std::round(p.x()/20))&&near(p.y()/20,std::round(p.y()/20));}check("Explicit snap anchors each entity corner "+QString::number(uml),snapped);w.history.undo();check("Explicit snap undo "+QString::number(uml),w.model.json()==old.json());
 }
 reset();w.model.get("ordine")->name="EntitaConIntestazioneLunga";w.model.get("riga")->chen={750,380};w.refresh();w.selectOnly("ordine");w.pick("riga",2);auto alignmentBefore=w.model.json();w.arrangeSelection(2);auto left=[&](QString id){return w.nodes[id]->pos().x()-w.nodes[id]->size.width()/2;};check("Left alignment uses actual edges of unequal-width shapes",near(left("ordine"),left("riga")));check("Selected anchor is identified visually",w.nodes["riga"]->layoutReference&&!w.nodes["ordine"]->layoutReference);w.history.undo();check("Edge alignment undo restores attributes and entities",w.model.json()==alignmentBefore);
 w.view->snapEnabled=true;w.arrangeSelection(0);check("Explicit row alignment takes precedence over grid",near(w.nodes["ordine"]->y(),w.nodes["riga"]->y()));w.history.undo();
 auto a=w.model.get("ordine");Object third=*a;third.id="third";third.name="Terza";third.chen={1400,260};w.model.objects<<third;w.refresh();w.selectOnly("ordine");w.pick("riga",2);w.pick("third",2);auto posA=w.nodes["ordine"]->pos(),posC=w.nodes["third"]->pos();w.arrangeSelection(4);auto bounds=[&](QString id){auto n=w.nodes[id];return QRectF(n->pos()-QPointF(n->size.width()/2,n->size.height()/2),n->size);};check("Horizontal distribution uses equal free gaps and fixed endpoints",near(bounds("riga").left()-bounds("ordine").right(),bounds("third").left()-bounds("riga").right())&&w.nodes["ordine"]->pos()==posA&&w.nodes["third"]->pos()==posC);
 for(auto id:{"ordine","riga","third"}){w.model.get(id)->chen.setY(220);}w.refresh();auto previous=w.model.json();w.arrangeSelection(5);check("Vertical distribution keeps outer figures fixed or refuses insufficient room",w.model.json()==previous);w.model.get("ordine")->chen.setY(-400);w.model.get("riga")->chen.setY(0);w.model.get("third")->chen.setY(800);w.refresh();w.arrangeSelection(5);check("Vertical distribution equalizes free gaps",near(bounds("riga").top()-bounds("ordine").bottom(),bounds("third").top()-bounds("riga").bottom()));
 reset();QStringList errors;auto schema=generateLogical(w.model,{},errors);w.model.logical=schema.json();w.switchLevel(true);auto ids=QStringList{schema.tables[0].id,schema.tables[1].id};w.selectOnly(ids[0]);w.pick(ids[1],2);before=w.model.json();w.view->snapEnabled=true;w.dragBefore=w.model;w.dragIds=w.selectionIds;w.moveDrag({13,7});w.finishGroupDrag();check("Logical snapping leaves conceptual positions intact",w.model.objects[0].chen==w.dragBefore.objects[0].chen&&!logicalStale(w.model));w.history.undo();check("Logical grid undo restores both levels",w.model.json()==before);w.arrangeSelection(3);check("Logical alignment uses table top edges",near(w.nodes[ids[0]]->pos().y()-w.nodes[ids[0]]->size.height()/2,w.nodes[ids[1]]->pos().y()-w.nodes[ids[1]]->size.height()/2));
 reset();
 for(bool shop:{true,false}){
  auto sample=shop?shopExample():purchaseExample();auto name=shop?QString("Negozio-panoramica"):QString("Acquisto-entita-associativa");QString error;Model parsed;
  check(name+" conceptual validation",sample.issues().isEmpty());check(name+" persisted three-level roundtrip",Model::parse(QJsonDocument(sample.json()).toJson(),parsed,error)&&parsed.json()==sample.json()&&!sample.logical.isEmpty()&&!sample.physical.isEmpty()&&!logicalStale(sample));
  LogicalSchema logical;LogicalSchema::parse(sample.logical,logical,error);check(name+" expected table count",logical.tables.size()==(shop?9:3));
  check(name+" generated SQL state is current",sample.physical["generatedText"]==sample.physical["draft"]&&sample.physical["generatedDigest"]==physicalDigest(logical,sample.physical));
  if(shop){bool weak=false,alternate=false,junction=false,invoice=false;for(const auto &t:logical.tables){if(t.source=="riga")weak=t.primaryKey().size()==2;if(t.source=="privato")alternate=t.uniqueKeys.size()==1&&t.foreignKeys.size()==1;if(t.source=="classifica")junction=t.primaryKey().size()==2&&t.foreignKeys.size()==2;if(t.source=="fattura")invoice=t.foreignKeys.size()==1&&t.uniqueKeys.size()==1;}check("Overview maps weak, ISA alternate key, junction and 1:1 constraints",weak&&alternate&&junction&&invoice);}

  for(auto profile:physicalProfiles()){auto config=physicalSwitchProfile(logical,sample.physical,profile);auto sql=generateSql(sample,config);check(name+" SQL "+profile,sql.errors.isEmpty()&&sql.text.contains("DECIMAL(19,4)"));}
  check(name+" saved",saveModel(output+"/"+name+".schema",sample,error));w.model=sample;w.uml=true;w.refresh();w.fit();qApp->processEvents();w.view->gridVisible=true;w.view->viewport()->update();qApp->processEvents();w.view->grab().save(output+"/"+name+"-griglia.png");auto rect=w.scene->itemsBoundingRect().adjusted(-20,-20,20,20);QImage image((rect.size()*1.2).toSize(),QImage::Format_ARGB32_Premultiplied);image.fill(w.theme.paper);QPainter painter(&image);painter.setRenderHint(QPainter::Antialiasing);w.scene->render(&painter,QRectF(QPointF(0,0),image.size()),rect);painter.end();image.save(output+"/"+name+"-diagramma.png");check(name+" vector PDF without grid",w.exportPdf(output+"/"+name+".pdf",QPageSize::A3,true,false,error));
  w.logicalView=true;w.refresh();w.fit();qApp->processEvents();w.view->grab().save(output+"/"+name+"-logico.png");w.logicalView=false;
 }
 reset();w.selectOnly("contiene");QScopedPointer<QMenu> menu(w.contextMenu("contiene",{}));check("Association help exists in the relationship context menu",menu->findChild<QAction*>("ctx.associationAttributes"));
 for(bool english:{false,true}){w.en=english;before=w.model.json();bool inspected=false;QTimer::singleShot(0,&w,[&]{auto d=w.findChild<QDialog*>("associationAttributesHelp");if(!d)return;inspected=d->findChild<QGraphicsView*>("associationIllustration")&&d->findChild<QPushButton*>("openAssociationExample");qApp->processEvents();d->grab().save(output+QString("/associazione-aiuto-%1.png").arg(english?"en":"it"));d->reject();});w.associationAttributesHelp();check("Association help is bilingual, illustrated and non-destructive "+QString::number(english),inspected&&w.model.json()==before);}
 reset();w.change("Unsaved",[](Model&m){m.get("ordine")->name="Da conservare";});before=w.model.json();QTimer::singleShot(0,&w,[&]{for(auto widget:QApplication::topLevelWidgets())if(auto message=qobject_cast<QMessageBox*>(widget))message->done(QMessageBox::Cancel);});w.loadTeachingExample(false);check("Opening a teaching example protects unsaved work on Cancel",w.model.json()==before);w.history.undo();w.loadTeachingExample(true);check("Welcome example loads conceptual UML with all three levels",w.uml&&!w.logicalView&&w.model.json()==shopExample().json());
 reset();
}
